package com.techprotech.agenda.modulos.productos.infraestructura.entidad;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.math.BigDecimal; import java.time.*;
@Getter @Setter @Entity @Table(name="comision_regla")
public class ReglaComisionEntidad { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="empresa_id",nullable=false) private Long empresaId; @Column(nullable=false,length=160) private String nombre; @Column(length=500) private String descripcion; @Column(nullable=false,length=20) private String concepto; @Column(nullable=false,length=20) private String alcance; @Column(name="servicio_id") private Long servicioId; @Column(name="producto_id") private Long productoId; @Column(name="categoria_producto_id") private Long categoriaProductoId; @Column(nullable=false,length=20) private String beneficiario; @Column(name="prestador_id") private Long prestadorId; @Column(name="tipo_calculo",nullable=false,length=20) private String tipoCalculo; @Column(name="base_calculo",nullable=false,length=30) private String baseCalculo; @Column(nullable=false,precision=12,scale=4) private BigDecimal valor; @Column(length=10) private String moneda; @Column(name="fecha_inicio") private LocalDate fechaInicio; @Column(name="fecha_fin") private LocalDate fechaFin; @Column(nullable=false) private int prioridad; @Column(nullable=false) private boolean activa; }
